class Solution {
    public boolean isHappy(int n) {
        int slow = n;
        int fast = n;
        // 初始相同也要先移动一次，不能一开始就判相遇。
        do {
            slow = getNext(slow);
            fast = getNext(getNext(fast));
        } while (slow != fast);
        return slow == 1;
    }

    private int getNext(int n) {
        int sum = 0;
        while (n > 0) {
            int digit = n % 10;
            sum += digit * digit;
            n /= 10;
        }
        return sum;
    }
}
